import{_ as l,a0 as p,w as a,s as u,I as e,x as t,a1 as n,A as i,ao as r}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"如何在 Ubuntu 15.04 / CentOS 7 上安装 Android Studio | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Ubuntu 15.04 / CentOS 7 上安装 Android Studio | LCTT (201512) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Ubuntu 15.04 / CentOS 7 上安装 Android Studio | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Ubuntu 15.04 / CentOS 7 上安装 Android Studio | LCTT (201512) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201512/20151123 How to install Android Studio on Ubuntu 15.04 or CentOS 7","title":"如何在 Ubuntu 15.04 / CentOS 7 上安装 Android Studio","tag":"201512","desc":""},"relativePath":"201512/20151123 How to install Android Studio on Ubuntu 15.04 or CentOS 7.md","filePath":"[post].md"}'),s={name:"201512/20151123 How to install Android Studio on Ubuntu 15.04 or CentOS 7.md"};function m(S,o,b,A,g,T){const d=p("Link");return a(),u("div",null,[o[22]||(o[22]=e("h1",{id:"如何在-ubuntu-15-04-centos-7-上安装-android-studio",tabindex:"-1"},[t("如何在 Ubuntu 15.04 / CentOS 7 上安装 Android Studio "),e("a",{class:"header-anchor",href:"#如何在-ubuntu-15-04-centos-7-上安装-android-studio","aria-label":"Permalink to “如何在 Ubuntu 15.04 / CentOS 7 上安装 Android Studio”"},"​")],-1)),e("p",null,[o[1]||(o[1]=t("随着最近几年智能手机的进步，安卓成为了最大的手机平台之一，在开发安卓应用中所用到的所有工具也都可以免费得到。Android Studio 是基于 ",-1)),n(d,{href:"https://www.jetbrains.com/idea/"},{default:i(()=>[...o[0]||(o[0]=[t("IntelliJ IDEA",-1)])]),_:1}),o[2]||(o[2]=t(" 用于开发安卓应用的集成开发环境（IDE）。它是 Google 2014 年发布的免费开源软件，继 Eclipse 之后成为主要的 IDE。",-1))]),o[23]||(o[23]=r(`<p>在这篇文章，我们一起来学习如何在 Ubuntu 15.04 和 CentOS 7 上安装 Android Studio。</p><h3 id="在-ubuntu-15-04-上安装" tabindex="-1">在 Ubuntu 15.04 上安装 <a class="header-anchor" href="#在-ubuntu-15-04-上安装" aria-label="Permalink to “在 Ubuntu 15.04 上安装”">​</a></h3><p>我们可以用两种方式安装 Android Studio。第一种是配置所需的库然后再安装它；另一种是从 Android 官方网站下载然后在本地编译安装。在下面的例子中，我们会使用命令行设置库并安装它。在继续下一步之前，我们需要确保我们已经安装了 JDK 1.6 或者更新版本。</p><p>这里，我打算安装 JDK 1.8。</p><pre><code>$ sudo add-apt-repository ppa:webupd8team/java
$ sudo apt-get update
$ sudo apt-get install oracle-java8-installer oracle-java8-set-default
</code></pre><p>验证 java 是否安装成功：</p><pre><code>poornima@poornima-Lenovo:~$ java  -version
</code></pre><p>现在，设置安装 Android Studio 需要的库</p><pre><code>$ sudo apt-add-repository ppa:paolorotolo/android-studio
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/11/Android-studio-repo.png" alt="Android-Studio-repo"></p><pre><code>$ sudo apt-get update
$ sudo apt-get install android-studio
</code></pre><p>上面的安装命令会在 /opt 目录下面安装 Android Studio。</p><p>现在，运行下面的命令启动安装向导：</p><pre><code>$ /opt/android-studio/bin/studio.sh
</code></pre><p>这会激活安装窗口。下面的截图展示了安装 Android Studio 的过程。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/11/Studio-setup.png" alt="安装 Android Studio"></p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/11/Install-type.png" alt="安装类型"></p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/11/Emulator-settings.png" alt="设置模拟器"></p><p>你点击了 Finish 按钮之后，就会显示同意协议页面。当你接受协议之后，它就开始下载需要的组件。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/11/Download.png" alt="下载组件"></p><p>这一步完成之后就结束了 Android Studio 的安装。当你重启 Android Studio 时，你会看到下面的欢迎界面，从这里你可以开始用 Android Studio 工作了。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/11/Welcome-screen.png" alt="欢迎界面"></p><h3 id="在-centos-7-上安装" tabindex="-1">在 CentOS 7 上安装 <a class="header-anchor" href="#在-centos-7-上安装" aria-label="Permalink to “在 CentOS 7 上安装”">​</a></h3>`,23)),e("p",null,[o[4]||(o[4]=t("现在再让我们来看看如何在 CentOS 7 上安装 Android Studio。这里你同样需要安装 JDK 1.6 或者更新版本。如果你不是 root 用户，记得在命令前面使用 ‘sudo’。你可以下载",-1)),n(d,{href:"http://www.oracle.com/technetwork/java/javase/downloads/jdk8-downloads-2133151.html"},{default:i(()=>[...o[3]||(o[3]=[t("最新版本",-1)])]),_:1}),o[5]||(o[5]=t("的 JDK。如果你已经安装了一个比较旧的版本，在安装新的版本之前你需要先卸载旧版本。在下面的例子中，我会通过下载需要的 rpm 包安装 JDK 1.8.0_65。",-1))]),o[24]||(o[24]=r(`<pre><code>[root@li1260-39 ~]# rpm -ivh jdk-8u65-linux-x64.rpm
Preparing... ################################# [100%]
Updating / installing...
1:jdk1.8.0_65-2000:1.8.0_65-fcs ################################# [100%]
Unpacking JAR files...
tools.jar...
plugin.jar...
javaws.jar...
deploy.jar...
rt.jar...
jsse.jar...
charsets.jar...
localedata.jar...
jfxrt.jar...
</code></pre><p>如果没有正确设置 Java 路径，你会看到错误信息。因此，设置正确的路径：</p><pre><code>export JAVA_HOME=/usr/java/jdk1.8.0_25/
export PATH=$PATH:$JAVA_HOME
</code></pre><p>检查是否安装了正确的版本：</p><pre><code>[root@li1260-39 ~]# java -version
java version &quot;1.8.0_65&quot;
Java(TM) SE Runtime Environment (build 1.8.0_65-b17)
Java HotSpot(TM) 64-Bit Server VM (build 25.65-b01, mixed mode)
</code></pre><p>如果你安装 Android Studio 的时候看到任何类似 “unable-to-run-mksdcard-sdk-tool:” 的错误信息，你可能要在 CentOS 7 64 位系统中安装以下软件包：</p><ul><li>glibc.i686</li><li>glibc-devel.i686</li><li>libstdc++.i686</li><li>zlib-devel.i686</li><li>ncurses-devel.i686</li><li>libX11-devel.i686</li><li>libXrender.i686</li><li>libXrandr.i686</li></ul>`,7)),e("p",null,[o[7]||(o[7]=t("通过从 ",-1)),n(d,{href:"http://developer.android.com/sdk/index.html"},{default:i(()=>[...o[6]||(o[6]=[t("Android 网站",-1)])]),_:1}),o[8]||(o[8]=t(" 下载 IDE 文件然后解压安装 studio 也是一样的。",-1))]),o[25]||(o[25]=r(`<pre><code>[root@li1260-39 tmp]# unzip android-studio-ide-141.2343393-linux.zip
</code></pre><p>移动 android-studio 目录到 /opt 目录</p><pre><code>[root@li1260-39 tmp]# mv /tmp/android-studio/ /opt/
</code></pre><p>需要的话你可以创建一个到 studio 可执行文件的符号链接用于快速启动。</p><pre><code>[root@li1260-39 tmp]# ln -s /opt/android-studio/bin/studio.sh /usr/local/bin/android-studio
</code></pre><p>现在在终端中启动 studio：</p><pre><code>[root@localhost ~]#studio
</code></pre><p>之后用于完成安装的截图和前面 Ubuntu 安装过程中的是一样的。安装完成后，你就可以开始开发你自己的 Android 应用了。</p><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>虽然发布不到一年，但是 Android Studio 已经替代 Eclipse 成为了 Android 的开发最主要的 IDE。它是唯一能支持 Google 之后将要提供的 Android SDK 和其它 Android 特性的官方 IDE 工具。那么，你还在等什么呢？赶快安装 Android Studio 来体验开发 Android 应用的乐趣吧。</p><hr>`,11)),e("p",null,[o[10]||(o[10]=t("via: ",-1)),n(d,{href:"http://linoxide.com/tools/install-android-studio-ubuntu-15-04-centos-7/"},{default:i(()=>[...o[9]||(o[9]=[t("http://linoxide.com/tools/install-android-studio-ubuntu-15-04-centos-7/",-1)])]),_:1})]),e("p",null,[o[14]||(o[14]=t("作者：",-1)),n(d,{href:"http://linoxide.com/author/bnpoornima/"},{default:i(()=>[...o[11]||(o[11]=[t("B N Poornima",-1)])]),_:1}),o[15]||(o[15]=t(" 译者：",-1)),n(d,{href:"http://mutouxiaogui.cn/blog/"},{default:i(()=>[...o[12]||(o[12]=[t("ictlyh",-1)])]),_:1}),o[16]||(o[16]=t(" 校对：",-1)),n(d,{href:"https://github.com/carolinewuyan"},{default:i(()=>[...o[13]||(o[13]=[t("Caroline",-1)])]),_:1})]),e("p",null,[o[19]||(o[19]=t("本文由 ",-1)),n(d,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...o[17]||(o[17]=[t("LCTT",-1)])]),_:1}),o[20]||(o[20]=t(" 原创编译，",-1)),n(d,{href:"https://linux.cn/"},{default:i(()=>[...o[18]||(o[18]=[t("Linux中国",-1)])]),_:1}),o[21]||(o[21]=t(" 荣誉推出",-1))])])}const v=l(s,[["render",m]]);export{x as __pageData,v as default};
